(()=>{
'use strict';
const byId=id=>document.getElementById(id);
const appearance=document.querySelector('.role-panel');
const preset=document.createElement('div');preset.className='role-autofill';preset.innerHTML='<label>What are you using NX for?<select id="nxUsePreset"><option value="modeling">Everyday part modeling</option><option value="assemblies">Assembly design</option><option value="surfacing">Surface and curve design</option><option value="manufacturing">Manufacturing / CAM preparation</option><option value="documentation">PMI and design documentation</option><option value="minimal">Minimal / distraction-free</option></select></label><button id="applyNxPreset" class="primary" type="button">Autofill suggested tabs</button><p id="nxPresetNote" aria-live="polite">Sets suggested tabs in Modeling, Sketching, and No Part. Shortcuts stay unchanged; every tab can be enabled later. CAM presets cover only the workspaces in this Studio, not a full Manufacturing ribbon.</p>';
appearance.insertBefore(preset,appearance.querySelector('.visibility-columns'));
byId('applyNxPreset').onclick=()=>{window.NX_ROLE_VISIBILITY.autofill(byId('nxUsePreset').value);byId('nxPresetNote').textContent='Suggested tabs applied in all three workspaces. Fine-tune any checkbox below. Shortcuts are unchanged. Tabs are hidden, not removed. Manufacturing application ribbons are not configured by this preset.'};
const panel=document.createElement('section');panel.className='role-panel merge-panel';panel.innerHTML='<div class="section-title"><div><span class="eyebrow">ROLE MIXER</span><h2>Merge .mtx roles</h2><p>Keep a base role, then choose which loaded role supplies each part. Files stay on your computer.</p></div><button id="loadMergeRoles" class="subtle" type="button">Load .mtx roles</button></div><input id="mergeRoleFiles" type="file" accept=".mtx,application/xml,text/xml" multiple hidden><p id="mergeFileStatus" aria-live="polite">Load two or more roles to mix their settings.</p><div id="mergeChoices" class="merge-choices"></div><p class="journal-note">This exports a separate role—it does not change the keyboard editor. Use roles from the same NX version. Custom commands may still require their original journals or add-ins.</p><div class="merge-buttons"><button id="previewMerge" class="subtle" type="button" disabled>Check merge</button><button id="exportMerge" class="primary" type="button" disabled>Export merged .mtx</button></div><pre id="mergeReport" aria-live="polite"></pre>';
appearance.after(panel);
const roles=[];
const PARTS=[['base','Base role','Shortcuts, command definitions, and all other settings stay from this role.'],['layout','Top ribbon tab settings','Ribbon tab visibility, order, and placement only. Other toolbars remain unchanged.'],['sidebar','Sidebar tabs and placement','Resource Bar tabs, visibility, docking, width, and pin settings.']];
const direct=(node,name)=>[...node.children].filter(x=>x.tagName===name);
const one=(node,name)=>direct(node,name)[0];
function parseRole(text){if(/<!DOCTYPE|<!ENTITY/i.test(text))throw Error('DTD/entity declarations are not supported');const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror')||xml.documentElement.tagName!=='NX_PROFILES')throw Error('Not a valid NX_PROFILES role');return xml}
function ensure(xml,parent,name){let node=one(parent,name);if(!node){node=xml.createElement(name);parent.append(node)}return node}
function profile(xml,name){let node=direct(xml.documentElement,'Profile').find(x=>x.getAttribute('name')===name);if(!node){node=xml.createElement('Profile');node.setAttribute('name',name);xml.documentElement.append(node)}return node}
function selected(key){const field=byId('merge-'+key);if(!field)return null;const value=field.value;return value===''?null:roles[Number(value)].xml}
function build(){const base=selected('base');if(!base)throw Error('Choose a base role');const xml=base.cloneNode(true);const root=xml.documentElement;
  const layout=selected('layout');if(layout)for(const donor of direct(layout.documentElement,'Profile')){const element=one(donor,'Layout');const lists=element&&one(element,'ActionLists');if(!lists)continue;const sourceTabs=direct(lists,'ActionList').filter(x=>x.getAttribute('type')==='ribbontab');const targetLists=ensure(xml,ensure(xml,profile(xml,donor.getAttribute('name')),'Layout'),'ActionLists');for(const old of direct(targetLists,'ActionList'))if(old.getAttribute('type')==='ribbontab')old.remove();for(const tab of sourceTabs)targetLists.append(xml.importNode(tab,true))}
  const sidebar=selected('sidebar');if(sidebar)for(const name of ['SessionSettings','TouchSessionSettings']){const session=one(sidebar.documentElement,name);const resource=session&&direct(session,'Setting').find(x=>x.getAttribute('name')==='ResourceBar');if(resource){const target=ensure(xml,root,name);for(const old of direct(target,'Setting'))if(old.getAttribute('name')==='ResourceBar')old.remove();target.append(xml.importNode(resource,true))}}
  root.setAttribute('name','NX_STUDIO_MERGED_'+Date.now());root.setAttribute('title','NX Shortcut Studio - Merged Role');return xml
}
function inspect(xml){const errors=[];const summary=[];const profiles=new Set();for(const p of direct(xml.documentElement,'Profile')){const scope=p.getAttribute('name');if(profiles.has(scope))errors.push('Duplicate profile: '+scope);profiles.add(scope);const lists=one(p,'Layout')&&one(one(p,'Layout'),'ActionLists');const tabs=lists?direct(lists,'ActionList').filter(x=>x.getAttribute('type')==='ribbontab'):[];const names=new Set();for(const tab of tabs){const name=tab.getAttribute('name');if(names.has(name))errors.push(scope+': duplicate ribbon tab '+name);names.add(name)}summary.push(scope+': '+tabs.length+' ribbon tabs')}for(const name of ['SessionSettings','TouchSessionSettings']){const session=one(xml.documentElement,name);const resource=session&&direct(session,'Setting').find(x=>x.getAttribute('name')==='ResourceBar');if(resource){const tabs=direct(resource,'Tab');const ids=new Set();for(const tab of tabs){const id=tab.getAttribute('id');if(ids.has(id))errors.push(name+': duplicate sidebar tab '+id);ids.add(id)}summary.push(name+': '+tabs.length+' sidebar tabs')}}return {errors,summary}}
function run(exportFile){try{const xml=build();const report=inspect(xml);const sources=PARTS.map(([key,label])=>label+': '+(byId('merge-'+key).value===''?'keep base':roles[Number(byId('merge-'+key).value)].name));byId('mergeReport').textContent=[...sources,'',...report.summary,'',...(report.errors.length?['Export blocked—choose a different tab source:',...report.errors]:['Tab structure checks passed. Base-role shortcuts and other settings are unchanged.','Test the merged role in NX before relying on it.'])].join('\n');if(exportFile&&!report.errors.length){const text='<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(xml.documentElement);parseRole(text);const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([text],{type:'application/xml'}));link.download='NX Shortcut Studio - Merged Role.mtx';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),3000)}}catch(error){byId('mergeReport').textContent='Merge failed: '+error.message}}
function renderChoices(){const old=Object.fromEntries(PARTS.map(([key])=>[key,byId('merge-'+key)?.value]));byId('mergeChoices').replaceChildren();for(const [key,label,description] of PARTS){const row=document.createElement('label');row.className='merge-choice';const title=document.createElement('strong');title.textContent=label;const note=document.createElement('small');note.textContent=description;const select=document.createElement('select');select.id='merge-'+key;if(key!=='base'){const option=document.createElement('option');option.value='';option.textContent='Keep base role';select.append(option)}roles.forEach((role,index)=>{const option=document.createElement('option');option.value=String(index);option.textContent=role.name;select.append(option)});if(old[key]!==undefined)select.value=old[key];select.onchange=()=>{byId('mergeReport').textContent='Sources changed. Check the merge before using it.'};row.append(title,note,select);byId('mergeChoices').append(row)}const enabled=roles.length>=2;byId('previewMerge').disabled=!enabled;byId('exportMerge').disabled=!enabled}
byId('loadMergeRoles').onclick=()=>byId('mergeRoleFiles').click();byId('mergeRoleFiles').onchange=async event=>{const failures=[];for(const file of event.target.files){try{if(file.size>10*1024*1024)throw Error('File exceeds 10 MB');const xml=parseRole(await file.text());roles.push({name:file.name,xml})}catch(error){failures.push(file.name+': '+error.message)}}renderChoices();byId('mergeFileStatus').textContent=roles.length+' roles loaded. '+failures.join(' | ');event.target.value='';byId('mergeReport').textContent='Choose a source for each section, then check or export the merge.'};
byId('previewMerge').onclick=()=>run(false);byId('exportMerge').onclick=()=>run(true);
window.NX_ROLE_MERGER={parseRole,inspect,build};
})();
